import { Effect, Schema } from "effect"

export class OutOfStock extends Schema.TaggedErrorClass<OutOfStock>()(
  "OutOfStock",
  {
    sku: Schema.String,
    requested: Schema.Number,
    available: Schema.Number
  }
) {}

