  inventory: ReadonlyMap<string, StockItem>,
  sku: string,
  quantity: number
) =>
  Effect.gen(function*() {
    const item = inventory.get(sku)
    if (item === undefined) {
      return yield* Effect.fail({ _tag: "UnknownSku" as const, sku })
